"""Meridian CRM RBAC permission check migrated from SYSTEM_OVERVIEW.md §5."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *object* and *record*.

    Permission rows are evaluated in their supplied order; the first exact
    role/object/action match is the applicable legacy matrix row.
    """
    role_id = user.get("ROLE_ID", "")

    permission_row = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            permission_row = row
            break

    # Missing permission rows deny access, including for ADMIN.
    if permission_row is None:
        return False

    # ADMIN bypasses scope only after a matching object/action row exists.
    if role_id == "ADMIN":
        allowed = True
    else:
        scope = permission_row.get("scope", "")
        if scope == "ALL":
            allowed = True
        elif scope == "TEAM":
            allowed = user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
        elif scope == "OWN":
            allowed = record.get("OWNER_UID", "") == user.get("USR_ID", "")
        else:
            # NONE and unrecognized/missing scopes deny by default.
            allowed = False

    if not allowed:
        return False

    if action == "DELETE":
        # Blank legacy boolean values mean N; only N is soft-deletable.
        delete_flag = record.get("DEL_FLG", "")
        if delete_flag == "":
            delete_flag = "N"
        return delete_flag == "N"

    return True
